const $=id=>document.getElementById(id), names=['x','y','z'];
let W=0,H=0,N=0,imgs=[],vox=[],pos=[0,0,0],busy=false;
const panels=['XY','XZ','YZ','3D'].map((name,i)=>{const section=document.createElement('section');section.className='panel';const title=document.createElement('h2');title.textContent=name;const c=document.createElement('canvas');c.tabIndex=0;c.setAttribute('aria-label',`Vista ${name}`);section.append(title,c);$('views').append(section);return {c,title,name,axis:[2,1,0,2][i],zoom:1,pan:[0,0],yaw:-.6,pitch:.6,tex:document.createElement('canvas')};});
names.forEach((n,i)=>{const label=document.createElement('label');label.append(document.createTextNode(n.toUpperCase()+' '));const r=document.createElement('input');r.type='range';r.min=0;r.max=0;r.value=0;r.id='r'+n;r.setAttribute('aria-label','Corte '+n);r.oninput=()=>{pos[i]=+r.value;update();};const out=document.createElement('output');out.id='o'+n;label.append(r,out);$('sliders').append(label);});
function spacing(){return ['sx','sy','sz'].map(id=>{const v=+$(id).value;return Number.isFinite(v)&&v>0?v:1;});}
function status(t){$('status').textContent=t;}
function update(){const sizes=[W,H,N];names.forEach((n,i)=>{$('r'+n).max=Math.max(0,sizes[i]-1);$('r'+n).value=pos[i];$('o'+n).textContent=`${sizes[i]?pos[i]+1:0}/${sizes[i]}`;});if(!N)return;const sx=spacing();status(`${W} × ${H} × ${N} · Z: ${imgs[pos[2]].name} · posición desde origen: ${pos.map((v,i)=>(v*sx[i]).toPrecision(4)).join(', ')} ${$('unit').value}`);textures();drawAll();}
function textures(){for(const p of panels.slice(0,3)){const tw=p.name==='YZ'?N:W,th=p.name==='XY'?H:p.name==='XZ'?N:H;p.tex.width=tw;p.tex.height=th;const ctx=p.tex.getContext('2d');if(p.name==='XY'){ctx.putImageData(vox[pos[2]],0,0);continue;}const d=ctx.createImageData(tw,th);for(let b=0;b<th;b++)for(let a=0;a<tw;a++){const z=p.name==='XZ'?b:a,x=p.name==='XZ'?a:pos[0],y=p.name==='XZ'?pos[1]:b;const src=(y*W+x)*4, dst=(b*tw+a)*4;d.data.set(vox[z].data.subarray(src,src+4),dst);}ctx.putImageData(d,0,0);}}
function dims(p){const [sx,sy,sz]=spacing(),ex=Math.max(1,Math.min(100,+$('ex').value||1));return p.name==='XY'?[W*sx,H*sy]:p.name==='XZ'?[W*sx,N*sz*ex]:[N*sz*ex,H*sy];}
function frame(p){const c=p.c,r=c.getBoundingClientRect();if(c.width!==Math.round(r.width)||c.height!==Math.round(r.height)){c.width=Math.round(r.width);c.height=Math.round(r.height);}const ctx=c.getContext('2d');ctx.fillStyle='#00131c';ctx.fillRect(0,0,c.width,c.height);return ctx;}
function transform(p){const [w,h]=dims(p),k=Math.min((p.c.width-30)/w,(p.c.height-30)/h)*p.zoom;return {x:p.c.width/2+p.pan[0]-w*k/2,y:p.c.height/2+p.pan[1]-h*k/2,w:w*k,h:h*k};}
function drawAll(){for(const p of panels){const ctx=frame(p);if(!N){ctx.fillStyle='#b5ced8';ctx.fillText('Carga un stack para comenzar',20,35);continue;}if(p.name==='3D'){draw3(p,ctx);continue;}const t=transform(p);ctx.imageSmoothingEnabled=false;ctx.drawImage(p.tex,t.x,t.y,t.w,t.h);const uv=p.name==='XY'?[(pos[0]+.5)/W,(pos[1]+.5)/H]:p.name==='XZ'?[(pos[0]+.5)/W,(pos[2]+.5)/N]:[(pos[2]+.5)/N,(pos[1]+.5)/H];ctx.strokeStyle='#00ffe0';ctx.beginPath();ctx.moveTo(t.x+uv[0]*t.w,t.y);ctx.lineTo(t.x+uv[0]*t.w,t.y+t.h);ctx.moveTo(t.x,t.y+uv[1]*t.h);ctx.lineTo(t.x+t.w,t.y+uv[1]*t.h);ctx.stroke();p.title.textContent=`${p.name} · ${names[p.axis].toUpperCase()} = ${pos[p.axis]+1} · ${Math.round(p.zoom*100)} %`;}}
function draw3(p,ctx){const [sx,sy,sz]=spacing(),ex=Math.max(1,Math.min(100,+$('ex').value||1)),d=[W*sx,H*sy,N*sz*ex],max=Math.max(...d),k=Math.min(p.c.width,p.c.height)*.65/max*p.zoom;const project=v=>{const x=v[0]-d[0]/2,y=v[1]-d[1]/2,z=v[2]-d[2]/2;const a=x*Math.cos(p.yaw)+z*Math.sin(p.yaw),b=-x*Math.sin(p.yaw)+z*Math.cos(p.yaw);return [p.c.width/2+p.pan[0]+a*k,p.c.height/2+p.pan[1]+(y*Math.cos(p.pitch)-b*Math.sin(p.pitch))*k,y*Math.sin(p.pitch)+b*Math.cos(p.pitch)];};const planes=[];function plane(im,a,b,c){planes.push({im,pt:[a,b,c].map(project)});}const z=(pos[2]+.5)*sz*ex,x=(pos[0]+.5)*sx,y=(pos[1]+.5)*sy;if($('all').checked){imgs.forEach((im,i)=>{let z=(i+.5)*sz*ex;plane(im.canvas,[0,0,z],[d[0],0,z],[0,d[1],z]);});}else{plane(panels[0].tex,[0,0,z],[d[0],0,z],[0,d[1],z]);plane(panels[1].tex,[0,y,0],[d[0],y,0],[0,y,d[2]]);plane(panels[2].tex,[x,0,0],[x,0,d[2]],[x,d[1],0]);}planes.sort((a,b)=>a.pt.reduce((s,v)=>s+v[2],0)-b.pt.reduce((s,v)=>s+v[2],0));for(const {im,pt:[a,b,c]}of planes){ctx.save();ctx.globalAlpha=$('all').checked?.65:.9;ctx.setTransform((b[0]-a[0])/im.width,(b[1]-a[1])/im.width,(c[0]-a[0])/im.height,(c[1]-a[1])/im.height,a[0],a[1]);ctx.drawImage(im,0,0);ctx.restore();ctx.strokeStyle='#21cfb5';ctx.beginPath();ctx.moveTo(...a.slice(0,2));ctx.lineTo(...b.slice(0,2));ctx.lineTo(b[0]+c[0]-a[0],b[1]+c[1]-a[1]);ctx.lineTo(...c.slice(0,2));ctx.closePath();ctx.stroke();}const o=project([0,0,0]);['X','Y','Z'].forEach((n,i)=>{const v=[0,0,0];v[i]=d[i];const q=project(v);ctx.strokeStyle=ctx.fillStyle=['#ff907a','#a4ee79','#72bfff'][i];ctx.beginPath();ctx.moveTo(...o.slice(0,2));ctx.lineTo(...q.slice(0,2));ctx.stroke();ctx.fillText(n,q[0]+4,q[1]-4);});p.title.textContent='3D · planos con textura · arrastra para girar';}
async function load(files,demo=false){if(busy)return;busy=true;$('files').disabled=$('demo').disabled=true;try{if(files.length<2||files.length>128)throw Error('Selecciona entre 2 y 128 imágenes.');files.sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true}));if(files.reduce((s,f)=>s+f.size,0)>256*1024**2)throw Error('El conjunto supera 256 MB.');const next=[],data=[];let w,h;for(const f of files){if(f.size>32*1024**2)throw Error('Imagen mayor de 32 MB.');status('Leyendo '+f.name);const im=await createImageBitmap(f);try{if(!w){w=im.width;h=im.height;if(w*h*files.length>32000000)throw Error('El stack supera 32 millones de vóxeles.');}if(im.width!==w||im.height!==h)throw Error('Todas las imágenes deben tener las mismas dimensiones.');const c=document.createElement('canvas');c.width=w;c.height=h;const ct=c.getContext('2d');ct.drawImage(im,0,0);next.push({name:f.name,canvas:c});data.push(ct.getImageData(0,0,w,h));}finally{im.close();}}imgs=next;vox=data;W=w;H=h;N=imgs.length;pos=[Math.floor(W/2),Math.floor(H/2),0];reset();if(demo)status($('status').textContent+' · DEMOSTRACIÓN, sin calibración física');}catch(e){status('No se cargó: '+e.message);}finally{busy=false;$('files').disabled=$('demo').disabled=false;}}
function reset(){panels.forEach(p=>{p.zoom=1;p.pan=[0,0];p.yaw=-.6;p.pitch=.6;});update();drawAll();}
$('files').onchange=e=>load([...e.target.files]);$('demo').onclick=async()=>{try{const files=await Promise.all(Array.from({length:10},async(_,i)=>{const name=`Z${String(i+1).padStart(2,'0')}.jpg`,r=await fetch('stack-demo/'+name);if(!r.ok)throw Error('No se encontró '+name);return new File([await r.blob()],name,{type:'image/jpeg'});}));await load(files,true);}catch(e){status(e.message);}};
$('reverse').onclick=()=>{imgs.reverse();vox.reverse();pos[2]=Math.max(0,N-1-pos[2]);update();};$('reset').onclick=reset;['sx','sy','sz','ex','unit','all'].forEach(id=>$(id).onchange=update);
function step(p,delta){const lim=[W,H,N][p.axis];pos[p.axis]=Math.max(0,Math.min(lim-1,pos[p.axis]+delta));update();}
for(const p of panels){let drag=null;p.c.onwheel=e=>{e.preventDefault();if(!N)return;if(e.shiftKey||p.name==='3D'){p.zoom=Math.max(.1,Math.min(20,p.zoom*Math.exp(-e.deltaY*.002)));drawAll();}else step(p,Math.sign(e.deltaY));};p.c.onpointerdown=e=>{p.c.focus();p.c.setPointerCapture(e.pointerId);drag={x:e.offsetX,y:e.offsetY,moved:false};};p.c.onpointermove=e=>{if(!drag)return;const dx=e.offsetX-drag.x,dy=e.offsetY-drag.y;if(Math.abs(dx)+Math.abs(dy)>1)drag.moved=true;if(p.name==='3D'&&!e.ctrlKey){p.yaw+=dx*.01;p.pitch+=dy*.01;}else{p.pan[0]+=dx;p.pan[1]+=dy;}drag.x=e.offsetX;drag.y=e.offsetY;drawAll();};p.c.onpointerup=e=>{if(drag&&!drag.moved&&N&&p.name!=='3D'){const t=transform(p),a=(e.offsetX-t.x)/t.w,b=(e.offsetY-t.y)/t.h;if(a>=0&&a<1&&b>=0&&b<1){if(p.name==='XY'){pos[0]=Math.floor(a*W);pos[1]=Math.floor(b*H);}if(p.name==='XZ'){pos[0]=Math.floor(a*W);pos[2]=Math.floor(b*N);}if(p.name==='YZ'){pos[2]=Math.floor(a*N);pos[1]=Math.floor(b*H);}update();}}drag=null;};p.c.onpointercancel=()=>drag=null;p.c.onkeydown=e=>{if(!N)return;if(['ArrowUp','ArrowDown','+','-','='].includes(e.key)){e.preventDefault();if(e.key.startsWith('Arrow'))step(p,e.key==='ArrowUp'?1:-1);else{p.zoom=Math.max(.1,Math.min(20,p.zoom*(e.key==='-'?.8:1.25)));drawAll();}}};}
new ResizeObserver(drawAll).observe($('views'));drawAll();
